def compute(vars):
    gross_liability = vars["v1"]
    interest_and_penalties = vars["v2"]
    total_including_interest_and_penalties = gross_liability + interest_and_penalties

    return {
        "value": total_including_interest_and_penalties,
        "trace": {
            "gross_liability": gross_liability,
            "interest_and_penalties": interest_and_penalties,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "currency"
            }
        }
    }
